 * takes none.
 *
 * @param {string} text
 * @param {number} [wpm=200] Reading rate in words per minute; a positive, finite number.
 * @returns {number} Whole minutes.
 */
function readingTimeMinutes(text, wpm = DEFAULT_WORDS_PER_MINUTE) {
